import{_ as t,o as l,c as o,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const B=JSON.parse('{"title":"CDS Jewel -- RBD Journal","description":"","frontmatter":{"title":"CDS Jewel -- RBD Journal","date":"2015-08-03T00:00:00.000Z","updated":"2015-08-04T00:00:00.000Z","tags":["RBD Journal Blueprint","Ceph 分布式存储","RBD 镜像复制","日志记录","跨数据中心","Ceph RBD","RADOS Block Device"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Jewel_--_RBD_Journal.md","filePath":"posts/2015/CDS_Jewel_--_RBD_Journal.md","lastUpdated":1780459816000}'),n={name:"posts/2015/CDS_Jewel_--_RBD_Journal.md"};function a(s,e,i,p,_,D){return l(),o("div",null,[...e[0]||(e[0]=[r("<p>会议纪要</p><p><strong>会议时间</strong>： 2023年某月某日</p><p><strong>会议地点</strong>： 线上会议</p><p><strong>参会人员</strong>： Jason、Hank、John、Vanessa等</p><p><strong>会议主题</strong>： RBD Journal Blueprint设计讨论</p><p><strong>会议内容</strong>：</p><ol><li><p><strong>RBD Journal Blueprint概述</strong> -Jason介绍了RBD Journal Blueprint的设计，旨在支持RBD镜像跨数据中心复制。 -该设计目标是实现通用性，不仅适用于lib rbd，未来也可能适用于MDS或其他客户端。 -设计基于liberated us API，与现有RBD代码和Journaling代码有所不同。</p></li><li><p><strong>设计决策</strong> -使用RNG算法将日志条目分散到多个对象上，提高效率。 -引入软最大大小限制，当日志对象满时，将关闭整个活动集，而不是单个对象。 -支持多读者和潜在的多写者，例如RBD镜像多磁盘的场景。 -引入新的工具来帮助恢复损坏的日志对象。</p></li><li><p><strong>与RBD的集成</strong> -新的RBD功能代码将允许动态启用和禁用日志记录功能。 -所有可变I/O操作（例如读写、快照操作）都将记录到日志中。 -首次打开镜像时，将进行回放模式，以同步日志。</p></li><li><p><strong>后续行动</strong> -Jason将提供代码链接，供大家查看和讨论。 -团队将继续改进和优化RBD Journal Blueprint。</p></li></ol><p><strong>关键术语</strong>：</p><ul><li>RBD (RADOS Block Device)</li><li>Journaling (日志记录)</li><li>MDS (Metadata Server)</li><li>OSD (Object Storage Device)</li><li>liberate us API</li><li>RNG (随机数生成器)</li><li>Soft maximum size</li><li>Replay mode</li></ul><p><strong>总结</strong>：</p><p>本次会议深入讨论了RBD Journal Blueprint的设计，旨在提升RBD镜像的可靠性和可用性，支持跨数据中心复制。设计采用了多种优化措施，包括日志条目分散、软最大大小限制和多读者支持等。团队将继续优化和改进该设计。</p>",11)])])}const g=t(n,[["render",a]]);export{B as __pageData,g as default};
